INSERT INTO portals_postmortemrecord VALUES(3,'cattle','None','Lucio','female','Approximately 5yrs','The cow was healthy on milking at 2pm. The footage of CCTV showed the cow writhing in pain at around 8pm. The cow succumbed to immediately after 23mins.',0,1,'Low','2025-03-01','20:20:00','The cadaver was bloated by observation.','yes','None',replace(replace('On PM, liver and spleen were normal.\r\nThe lungs was odematous and hyperemic. On incision, all lopes were congested and blood filled.\r\nHence the caused of dead was due to acute pneumonia.','\r',char(13)),'\n',char(10)),'no','no','no','None','burial','Joseph Koech','Tangula','+254 720 581554','Kirui Richard and Sigei','VTB00143','0727091292','Rkk',NULL,4,137,'Soin veterinary Services','technologist',NULL,NULL);
