PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "user_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "is_vet_officer" bool NOT NULL, "is_farmer" bool NOT NULL, "is_official" bool NOT NULL, "first_name" varchar(100) NOT NULL, "last_name" varchar(100) NOT NULL, "email" varchar(254) NULL, "phone_number" varchar(13) NOT NULL, "specialization" varchar(100) NULL, "county" varchar(100) NULL, "location" varchar(100) NULL, "vet_category" varchar(100) NULL, "registration_number" varchar(100) NULL, "licence_number" varchar(100) NULL, "subcounty" varchar(100) NULL, "supervisor" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "user_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "user_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "user_shopproducttype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(45) NOT NULL);
CREATE TABLE IF NOT EXISTS "user_farmer" ("user_id" bigint NOT NULL PRIMARY KEY REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "county" varchar(100) NOT NULL, "location" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "user_vet_officer" ("user_id" bigint NOT NULL PRIMARY KEY REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "user_supplierproduct" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "supplier" varchar(64) NOT NULL, "product_id" bigint NOT NULL REFERENCES "user_productitem" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "user_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "user_productitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(45) NOT NULL, "description" varchar(200) NULL, "product_type_id" bigint NOT NULL REFERENCES "user_shopproducttype" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "user_farm" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "farm_name" varchar(100) NOT NULL, "location" varchar(100) NOT NULL, "farm_owner_id" bigint NOT NULL REFERENCES "user_farmer" ("user_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "email" varchar(254) NOT NULL UNIQUE, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" bigint NOT NULL REFERENCES "account_emailaddress" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_gestationmonitoring" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "gestation_date" date NOT NULL, "repeat_date" date NULL, "expected_delivery_date" date NULL);
CREATE TABLE IF NOT EXISTS "portals_weeklymilkrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "week_start_date" date NOT NULL, "total_quantity" real NOT NULL, "cow_name_id" bigint NOT NULL REFERENCES "portals_lactatingcow" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_salesofmilk" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_sales" date NOT NULL, "number_of_cows_milked" integer unsigned NOT NULL CHECK ("number_of_cows_milked" >= 0), "total_kgs_milked" real NOT NULL, "milk_sales_to" varchar(12) NOT NULL, "buyer_contact" varchar(50) NOT NULL, "price_per_kg" real NOT NULL, "total_cash_received" real NOT NULL, "balance" real NULL, "comment" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_newanimal" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "reg_no" varchar(100) NOT NULL, "source" varchar(50) NOT NULL, "farmer_name" varchar(100) NOT NULL, "animal_type" varchar(100) NOT NULL, "breed" varchar(100) NOT NULL, "breeding_level" varchar(100) NOT NULL, "defect" varchar(3) NOT NULL, "defect_reason" text NOT NULL, "animal_color" varchar(100) NOT NULL, "market_value" decimal NOT NULL, "medical_history" varchar(3) NOT NULL, "assessed_by_vet" varchar(3) NOT NULL, "insured" varchar(3) NOT NULL, "insuring_company" varchar(100) NOT NULL, "date_added" date NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_monthlymilkrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "month" date NOT NULL, "total_quantity" real NOT NULL, "cow_name_id" bigint NOT NULL REFERENCES "portals_lactatingcow" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_minerals" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_purchase" date NOT NULL, "mineral_type" varchar(15) NOT NULL, "quantity" varchar(255) NOT NULL, "company" varchar(255) NOT NULL, "expiry_date" date NOT NULL, "cost" decimal NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_livestock" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "animal_type" varchar(50) NOT NULL, "breed_category" varchar(50) NOT NULL, "date_added" date NOT NULL, "no_of_animals" real NOT NULL, "no_of_males" real NOT NULL, "no_of_females" real NOT NULL, "no_of_adults" real NOT NULL, "no_of_young" real NOT NULL, "no_of_dead" real NOT NULL, "reason_for_death" varchar(100) NOT NULL, "comment" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_heatsignmonitoring" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "reg_no" varchar(20) NOT NULL, "status" varchar(10) NOT NULL, "date_of_heat_sign" date NOT NULL, "date_of_heat_monitoring" date NOT NULL, "exp_date_of_repeated_heat" date NOT NULL, "reason_skip_monitoring" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_deadanimal" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(30) NOT NULL, "farm_name" varchar(100) NOT NULL, "no_of_affected" real NOT NULL, "gender" varchar(10) NOT NULL, "breed" varchar(100) NOT NULL, "sickness_period" varchar(30) NOT NULL, "cause_of_death" varchar(30) NOT NULL, "death_date" date NULL, "death_time" time NULL, "signs_before_death" varchar(200) NULL, "postmortem_by_vet" varchar(3) NOT NULL, "safety_precaution" varchar(30) NOT NULL, "comment" varchar(300) NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_dailymilkrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NULL, "time" time NULL, "total_quantity" real NULL, "cow_name_id" bigint NOT NULL REFERENCES "portals_lactatingcow" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_culling" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "age" varchar(100) NOT NULL, "gender" varchar(100) NOT NULL, "animal_type" varchar(100) NOT NULL, "breed" varchar(100) NOT NULL, "culling_method" varchar(100) NOT NULL, "no_of_culled" real NOT NULL, "culling_reason" varchar(100) NOT NULL, "reg_no" varchar(100) NOT NULL UNIQUE, "culling_date" date NOT NULL, "culling_price" decimal NOT NULL, "comment" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_animalsale" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "number_sold" integer NOT NULL, "name" varchar(100) NOT NULL, "reg_no" varchar(100) NOT NULL, "date_sold" date NOT NULL, "age" integer NOT NULL, "breed" varchar(100) NOT NULL, "sex" varchar(10) NOT NULL, "weight" decimal NOT NULL, "selling_price" decimal NOT NULL, "reason" text NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_site" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "domain" varchar(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "socialaccount_socialapp_sites" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "socialapp_id" integer NOT NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "socialaccount_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "uid" varchar(191) NOT NULL, "last_login" datetime NOT NULL, "date_joined" datetime NOT NULL, "extra_data" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "socialaccount_socialapp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "name" varchar(40) NOT NULL, "client_id" varchar(191) NOT NULL, "secret" varchar(191) NOT NULL, "key" varchar(191) NOT NULL);
CREATE TABLE IF NOT EXISTS "socialaccount_socialtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "token_secret" text NOT NULL, "expires_at" datetime NULL, "account_id" bigint NOT NULL REFERENCES "socialaccount_socialaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "app_id" bigint NOT NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_milkrecord_employee_name" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "milkrecord_id" bigint NOT NULL REFERENCES "portals_milkrecord" ("id") DEFERRABLE INITIALLY DEFERRED, "employees_id" bigint NOT NULL REFERENCES "portals_employees" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_milkrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "time_of_milking" varchar(10) NOT NULL, "quantity" real NOT NULL, "cow_name_id" bigint NOT NULL REFERENCES "portals_lactatingcow" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "employee_name_id" bigint NOT NULL REFERENCES "portals_employees" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_veterinarydrugs" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "category" varchar(15) NOT NULL, "company" varchar(50) NOT NULL, "expiry_date" date NOT NULL, "strange_condition" varchar(255) NOT NULL, "vet_reg" varchar(255) NOT NULL, "cost" decimal NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "date_of_purchase" date NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_lactatingcow" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cow_name" varchar(100) NOT NULL UNIQUE, "sire_details" varchar(100) NOT NULL, "breed" varchar(50) NOT NULL, "breeding_level" varchar(50) NOT NULL, "age" integer unsigned NOT NULL CHECK ("age" >= 0), "calving_down_date" date NOT NULL, "no_of_calves" integer unsigned NOT NULL CHECK ("no_of_calves" >= 0), "average_daily_milk" real NOT NULL, "lactation_stage" varchar(10) NOT NULL, "expected_date_of_drying_off" date NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "reg_no" varchar(50) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_calf" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name_given" varchar(100) NOT NULL,"registration_number" varchar(100) NOT NULL UNIQUE DEFAULT '',"dam_details" varchar(100) NOT NULL, "birth_date" date NOT NULL, "breed" varchar(100) NOT NULL, "gender" varchar(10) NOT NULL, "sire_details" varchar(100) NOT NULL, "color" varchar(100) NOT NULL, "birth_weight" real NOT NULL, "medical_conditions" varchar(100) NOT NULL,  "registration_date" date NULL, "expected_weaning" date NULL, "breeding_level" varchar(100) NOT NULL, "comments" varchar(100) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_veterinarybills" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_billing" date NOT NULL, "bill_category" varchar(20) NOT NULL, "amount" decimal NOT NULL,"amount_billed" decimal NOT NULL, "balance" decimal NOT NULL, "billing_details" varchar(255) NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_dairyhygiene" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "chemical_name" varchar(255) NOT NULL,"trade_name" varchar(255) NOT NULL, "date_of_purchase" date NOT NULL, "item_purchased" varchar(255) NOT NULL, "company" varchar(255) NOT NULL, "quantity" varchar(255) NOT NULL, "cost" decimal NOT NULL, "expiry_date" date NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_feeds" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_purchase" date NOT NULL, "feed_type" varchar(15) NOT NULL,"quantity_purchased" varchar(255) NOT NULL,"trade_name" varchar(255) NOT NULL,"weight" varchar(255) NOT NULL, "company" varchar(255) NOT NULL, "expiry_date" date NOT NULL, "cost" decimal NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_dairyequipment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(40) NOT NULL, "date_of_purchase" date NOT NULL, "quantity" varchar(255) NOT NULL, "equipment_type" varchar(255) NOT NULL,"model_number" varchar(255) NOT NULL, "company" varchar(255) NOT NULL, "cost" decimal NOT NULL, "source" varchar(255) NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_livestockinsurance" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "number_insured"decimal NOT NULL,"breed" varchar(50),"animal_species" varchar(50) NOT NULL, "company" varchar(255) NOT NULL, "mode_of_payment" varchar(255) NOT NULL, "payment_date" date NOT NULL, "total" decimal NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_pregnancymonitoring" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "reg_no" varchar(50) NOT NULL, "date_of_ai" date NOT NULL, "exp_heat_date" date NULL,"repeat_heat_date" date NULL, "first_preg_diag_date" date NULL, "steaming_up_date" date NULL, "expected_dob" date NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_archaricides" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_purchase" date NOT NULL, "chemical_name" varchar(50) NOT NULL, "quantity" varchar(255) NOT NULL, "company" varchar(255) NOT NULL, "application_rate" varchar(255) NOT NULL, "expiry_date" date NOT NULL, "times_used" varchar(255) NOT NULL, "cost" decimal NOT NULL, "comment" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "trade_name" varchar(50) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_salaries" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "employee_position" varchar(50) NOT NULL, "employee_name_id" bigint NOT NULL REFERENCES "portals_employees" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "amount" decimal NOT NULL, "balance" decimal NOT NULL, "bank_account" varchar(255) NOT NULL, "comment" text NOT NULL, "mode_of_payment" varchar(255) NOT NULL, "payment_date" date NOT NULL, "payment_type" varchar(255) NOT NULL, "salary_amount" decimal NOT NULL, "identification" varchar(255) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "portals_laboratoryrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(10) NOT NULL, "other_livestock" varchar(100) NULL, "name_of_animal" varchar(100) NOT NULL, "registration_number" varchar(100) NOT NULL, "age_of_animal" varchar(10) NOT NULL, "sex_of_animal" varchar(6) NOT NULL, "history_of_animal" text NOT NULL, "clinical_signs" text NOT NULL, "type_of_sample_collected" varchar(20) NOT NULL, "date_of_sampling" date NOT NULL, "sample_storage_condition" varchar(255) NOT NULL, "means_of_transportation" varchar(10) NOT NULL, "sample_rating" varchar(20) NOT NULL, "owner_name" varchar(100) NOT NULL, "owner_village" varchar(100) NOT NULL, "owner_mobile_number" varchar(15) NOT NULL, "vet_in_charge_name" varchar(100) NOT NULL, "vet_registration_number" varchar(100) NOT NULL, "vet_mobile_number" varchar(15) NOT NULL, "signature" varchar(255) NOT NULL, "stamp" varchar(255) NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_livestockincident" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(10) NOT NULL, "animal_name" varchar(100) NOT NULL, "sex" varchar(6) NOT NULL, "age" integer unsigned NOT NULL CHECK ("age" >= 0), "case_history" text NOT NULL, "number_of_sick_animals" integer unsigned NOT NULL CHECK ("number_of_sick_animals" >= 0), "morbidity_rate" varchar(40) NOT NULL, "incidence_date" date NOT NULL, "incidence_time" time NOT NULL, "cadaver_signs" text NOT NULL, "open_for_pm" varchar(3) NOT NULL, "no_pm_reason" text NULL, "path_condition" text NOT NULL, "sample_sent" varchar(3) NOT NULL, "cause_notifiable" varchar(3) NOT NULL, "cause_zoonotic" varchar(3) NOT NULL, "precaution" text NOT NULL, "disposal_way" varchar(10) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_surgicalrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category_affected" varchar(10) NOT NULL, "other_livestock_category" varchar(100) NULL, "name_of_animal" varchar(100) NOT NULL, "registration_number" varchar(100) NOT NULL, "sex_of_animal" varchar(6) NOT NULL, "age_of_animal" varchar(5) NOT NULL, "nature_of_surgery" varchar(10) NOT NULL, "type_of_surgery" varchar(50) NOT NULL, "other_surgery" varchar(100) NULL, "status_before_operation" varchar(15) NOT NULL, "pre_operative_management" text NULL, "date_of_operation" date NOT NULL, "post_operation_management" text NULL, "prognosis_of_patient" varchar(15) NOT NULL, "comment" text NULL, "owner_name" varchar(100) NOT NULL, "owner_village" varchar(100) NOT NULL, "owner_mobile_number" varchar(15) NOT NULL, "vet_in_charge" varchar(100) NOT NULL, "vet_registration_number" varchar(100) NOT NULL, "vet_mobile_number" varchar(15) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_client" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_enrollment" date NOT NULL, "full_name" varchar(255) NOT NULL, "mobile_number" varchar(15) NOT NULL, "location" varchar(255) NOT NULL, "livestock_interest" text NULL, "remarks" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_diary" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "main_activity" varchar(255) NOT NULL, "client_contact" varchar(15) NOT NULL, "remarks" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "time_of_event" time NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_userprogress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "score" real NOT NULL, "completed_at" datetime NOT NULL, "section_id" bigint NOT NULL REFERENCES "portals_section" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_cpdquestions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "question_text" varchar(255) NOT NULL, "section_id" bigint NOT NULL REFERENCES "portals_section" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_cpdchoices" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "choice_text" varchar(255) NOT NULL, "is_correct" bool NOT NULL, "question_id" bigint NOT NULL REFERENCES "portals_cpdquestions" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_comment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "author_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "section_id" bigint NOT NULL REFERENCES "portals_section" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_section" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "content" text NOT NULL, "lesson_id" bigint NOT NULL REFERENCES "portals_tutorial" ("id") DEFERRABLE INITIALLY DEFERRED, "file" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "is_paid" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "user_official" ("user_id" bigint NOT NULL PRIMARY KEY REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "employment_number" varchar(100) NOT NULL, "sub_county" varchar(100) NOT NULL, "designation" varchar(50) NOT NULL, "county" varchar(50) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_livestockexaminationrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(50) NOT NULL, "other_category" varchar(100) NULL, "age_of_animal" integer unsigned NOT NULL CHECK ("age_of_animal" >= 0), "breed" varchar(100) NOT NULL, "sex_of_animal" varchar(10) NOT NULL, "number_of_animals" integer unsigned NOT NULL CHECK ("number_of_animals" >= 0), "origin_of_animal" varchar(100) NOT NULL, "destination" varchar(100) NOT NULL, "reason_for_examination" varchar(50) NOT NULL, "recommendation" text NOT NULL, "owner_name" varchar(100) NOT NULL, "owner_mobile_number" varchar(15) NOT NULL, "veterinary_officer_in_charge" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL, "veterinary_officer_mobile_number" varchar(15) NOT NULL, "veterinary_officer_signature" text NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_monthlyreport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_submission" date NOT NULL, "sub_county" varchar(100) NOT NULL, "ward_level" varchar(100) NOT NULL, "submitted_by" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL, "phone_number" varchar(15) NOT NULL, "uploaded_report" varchar(100) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_movementpermit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_permit" date NOT NULL, "sub_county_district" varchar(100) NOT NULL, "ward_level" varchar(100) NOT NULL, "authorized_by" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL, "phone_number" varchar(15) NOT NULL, "uploaded_permit" varchar(100) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_noobjection" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_confirmation" date NOT NULL, "sub_county_district" varchar(100) NOT NULL, "ward_level" varchar(100) NOT NULL, "confirmed_by" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL, "phone_number" varchar(15) NOT NULL, "uploaded_no_objection_form" varchar(100) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_yearlyreport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_submission" date NOT NULL, "sub_county" varchar(100) NOT NULL, "ward_level" varchar(100) NOT NULL, "submitted_by" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL, "phone_number" varchar(15) NOT NULL, "uploaded_report" varchar(100) NOT NULL, "assigned_to_official_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_quarterlyreport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_submission" date NOT NULL, "sub_county" varchar(100) NOT NULL, "ward_level" varchar(100) NOT NULL, "submitted_by" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL, "phone_number" varchar(15) NOT NULL, "uploaded_report" varchar(100) NOT NULL, "assigned_to_official_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_practitioner" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "first_name" varchar(20) NOT NULL, "last_name" varchar(20) NOT NULL, "phone_number" varchar(20) NOT NULL, "email" varchar(100) NOT NULL, "county" varchar(30) NOT NULL, "subcounty" varchar(30) NOT NULL, "ward" varchar(30) NOT NULL, "area_of_operation" varchar(30) NOT NULL, "specialization" varchar(50) NOT NULL, "vet_category" varchar(50) NOT NULL, "registration_number" varchar(50) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "employment_status" varchar(50) NOT NULL, "reg_date" date NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_sampleprocessing" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(10) NOT NULL, "sample_rating" varchar(20) NOT NULL, "animal_name" varchar(100) NOT NULL, "registration_number" varchar(100) NOT NULL, "sex_of_animal" varchar(6) NOT NULL, "age_of_animal" varchar(10) NOT NULL, "date_of_reception" date NOT NULL, "date_of_sample_processing" date NOT NULL, "date_of_sample_results" date NOT NULL, "laboratory_findings" text NOT NULL, "comment" text NULL, "owner_name" varchar(100) NOT NULL, "owner_village" varchar(100) NOT NULL, "owner_mobile_number" varchar(15) NOT NULL, "lab_technologist_name" varchar(100) NOT NULL, "lab_technologist_registration_number" varchar(100) NOT NULL, "lab_technologist_mobile_number" varchar(15) NOT NULL, "laboratory_name" varchar(100) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "type_of_sample_received" varchar(255) NOT NULL, "number_of_days_for_processing" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_diseasereport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(20) NOT NULL, "other_livestock_category" varchar(50) NULL, "number_of_animals_affected" integer NOT NULL, "sex_of_animals_affected" varchar(10) NOT NULL, "age_of_animals_affected" varchar(10) NOT NULL, "clinical_signs" text NOT NULL, "number_of_dead_animals" integer NOT NULL, "propose_control_measures" text NOT NULL, "sample_taken_to_lab" varchar(3) NOT NULL, "tentative_diagnosis" text NOT NULL, "village_disease_occurred" varchar(100) NOT NULL, "sub_county" varchar(100) NOT NULL, "county" varchar(100) NOT NULL, "owner_name" varchar(100) NOT NULL, "owner_mobile_number" varchar(20) NOT NULL, "vet_in_charge_name" varchar(100) NOT NULL, "vet_registration_number" varchar(50) NOT NULL, "vet_mobile_number" varchar(20) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "date" date NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_calvingrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_calving" date NOT NULL, "insemination_date" date NULL, "days_to_calving_down" integer unsigned NOT NULL CHECK ("days_to_calving_down" >= 0), "cow_name" varchar(100) NOT NULL, "registration_number" varchar(50) NULL, "calving_procedure" varchar(20) NOT NULL, "rab_status" varchar(20) NOT NULL, "calf_sex" varchar(6) NOT NULL, "calf_status" varchar(10) NOT NULL, "reason_for_dead_foetus" varchar(50) NULL, "comment" text NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "hours_for_natural_expulsion" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "portals_quizresult" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "score" real NOT NULL, "passed" varchar(10) NOT NULL, "timestamp" datetime NOT NULL, "section_id" bigint NOT NULL REFERENCES "portals_section" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "failed_attempts" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_assessmentrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(20) NOT NULL, "other_category" varchar(50) NULL, "date_of_assessment" date NOT NULL, "name_of_animal" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL, "color_of_animal" varchar(50) NOT NULL, "age_of_animal" integer unsigned NOT NULL CHECK ("age_of_animal" >= 0), "sex_of_animal" varchar(10) NOT NULL, "number_of_animals" integer unsigned NOT NULL CHECK ("number_of_animals" >= 0), "origin_of_animal" varchar(100) NOT NULL, "place_of_assessment" varchar(20) NOT NULL, "destination" varchar(100) NOT NULL, "reason_for_assessment" varchar(50) NOT NULL, "recommendation" text NULL, "owner_of_animal" varchar(100) NOT NULL, "owner_mobile_number" varchar(15) NOT NULL, "veterinary_practitioner_in_charge" varchar(100) NOT NULL, "practitioner_registration_number" varchar(50) NOT NULL, "practitioner_contact" varchar(15) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "signature_and_stamp" text NULL);
CREATE TABLE IF NOT EXISTS "portals_tutorial" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "lesson" varchar(255) NOT NULL, "is_paid" bool NOT NULL, "points" integer NOT NULL, "unit_price" decimal NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "cpd_number" varchar(30) NOT NULL, "presented_by" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_supplier" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_enrollment" date NOT NULL, "name" varchar(100) NOT NULL, "mobile_number" varchar(15) NOT NULL, "location" varchar(100) NOT NULL, "business_name" varchar(100) NOT NULL, "mode_of_payment" varchar(20) NOT NULL, "account_details" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_pricelist" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_purchase" date NOT NULL, "product_name" varchar(100) NOT NULL, "manufacturing_company" varchar(100) NOT NULL, "buying_price" decimal NOT NULL, "retail_price" decimal NOT NULL, "wholesale_price" decimal NOT NULL, "expiring_date" date NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_customer" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_enrollment" date NOT NULL, "name" varchar(100) NOT NULL, "mobile_number" varchar(15) NOT NULL, "location" varchar(100) NOT NULL, "remarks" text NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_creditor" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_transaction" date NOT NULL, "name" varchar(255) NOT NULL, "mobile_number" varchar(15) NOT NULL, "total_amount_to_pay" decimal NOT NULL, "amount_paid" decimal NOT NULL, "balance_to_pay" decimal NOT NULL, "agreed_date_of_balance_payment" date NOT NULL, "remarks" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_employee" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "slaughterhouse" varchar(60) NOT NULL, "name" varchar(255) NOT NULL, "id_number" varchar(100) NOT NULL, "mobile_number" varchar(15) NOT NULL, "position" varchar(50) NOT NULL, "medical_license_status" varchar(50) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "enrollment_date" date NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_butcher" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "id_number" varchar(100) NOT NULL, "mobile_number" varchar(15) NOT NULL, "medical_license_status" varchar(50) NOT NULL, "livestock_slaughtered" varchar(50) NOT NULL, "meat_container_number" varchar(50) NOT NULL, "meat_carrier_number" varchar(50) NOT NULL, "means_of_transport" varchar(50) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "enrollment_date" date NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_debtor" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_transaction" date NOT NULL, "name" varchar(255) NOT NULL, "mobile_number" varchar(15) NOT NULL, "total_invoice_amount" decimal NOT NULL, "total_amount_to_pay" decimal NOT NULL, "amount_paid" decimal NOT NULL, "balance_to_pay" decimal NOT NULL, "remarks" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "correction_done" varchar(20) NOT NULL, "grand_total" decimal NOT NULL, "invoice_no" varchar(40) NOT NULL, "previous_balance" decimal NOT NULL, "amount_of_correction" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_employees" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "employee_name" varchar(100) NOT NULL, "id_no" varchar(20) NOT NULL UNIQUE, "phone_no" varchar(15) NOT NULL, "district" varchar(50) NOT NULL, "village" varchar(50) NOT NULL, "next_of_kin" varchar(100) NOT NULL, "next_of_kin_phone_no" varchar(15) NOT NULL, "chief_phone_no" varchar(15) NOT NULL, "employee_position" varchar(50) NOT NULL, "salary" decimal NOT NULL, "payment_method" varchar(30) NOT NULL, "bank_account" varchar(30) NULL, "mode_of_employment" varchar(20) NOT NULL, "contract_rewal_period" integer NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "chief_name" varchar(50) NOT NULL, "county" varchar(50) NOT NULL, "enrollment_date" date NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_slaughterhouse" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "county" varchar(255) NOT NULL, "sub_county" varchar(255) NOT NULL, "location" varchar(255) NOT NULL, "slaughterhouse_category" varchar(50) NOT NULL, "livestock_slaughtered" varchar(255) NOT NULL, "number_of_employees" integer NOT NULL, "roller_mark_number" varchar(50) NOT NULL, "inspector_name" varchar(255) NOT NULL, "inspector_registration_number" varchar(100) NOT NULL, "inspector_employment_number" varchar(100) NOT NULL, "inspector_mobile_number" varchar(15) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "slaughterhouse_status" varchar(50) NOT NULL, "reg_date" date NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_attempt" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "score" integer NOT NULL, "attempt_number" integer NOT NULL, "timestamp" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_userretake" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "retakes_left" integer NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_artificialinsemination" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cow_name" varchar(255) NOT NULL, "reg_no" varchar(255) NOT NULL, "dam_details" text NOT NULL, "sire_details" text NOT NULL, "no_of_repeats" integer NOT NULL, "abortion_status" varchar(3) NOT NULL, "time_of_heat_sign" time NOT NULL, "date_of_heat_sign" date NOT NULL, "insemination_time" time NOT NULL, "breed_used" varchar(255) NOT NULL, "bull_name" varchar(255) NOT NULL, "bull_reg_no" varchar(255) NOT NULL, "semen_source" varchar(255) NOT NULL, "heat_sign_mtr_date" date NOT NULL, "repeat_heat_date" date NOT NULL, "first_pd_date" date NOT NULL, "expected_delivery_date" date NOT NULL, "owners_name" varchar(255) NOT NULL, "village" varchar(255) NOT NULL, "contact" varchar(15) NOT NULL, "vet_name" varchar(255) NOT NULL, "vet_reg_no" varchar(254) NOT NULL, "vet_contact" varchar(15) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "insemination_date" date NOT NULL, "insemination_status" varchar(20) NOT NULL, "farm_name" varchar(255) NOT NULL, "assigned_to_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "semen_type" varchar(20) NOT NULL, "assigned_to_official_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "sub_county" varchar(25) NOT NULL, "ward" varchar(25) NOT NULL, "signature_stamp" text NULL, "provided_by" varchar(255) NOT NULL, "species" varchar(10) NOT NULL, "vet_category" varchar(30) NOT NULL, "assigned_by_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, other_breed TEXT, other_source TEXT, rab_status TEXT);
CREATE TABLE IF NOT EXISTS "portals_deworming" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "species_targeted" varchar(10) NOT NULL, "other" varchar(255) NULL, "no_of_adults" integer NOT NULL, "no_of_young_ones" integer NOT NULL, "body_conditions" text NOT NULL, "deworming_date" date NOT NULL, "drug_of_choice" varchar(255) NOT NULL, "parasites" varchar(255) NOT NULL, "withdrawal_period" varchar(255) NOT NULL, "side_effects" text NULL, "nxt_deworming_date" date NOT NULL, "farmer_name" varchar(255) NOT NULL, "village" varchar(255) NOT NULL, "contact" varchar(15) NOT NULL, "vet_name" varchar(255) NOT NULL, "reg_no" varchar(255) NOT NULL, "vet_contact" varchar(15) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "provided_by" varchar(255) NOT NULL, "animal_name" varchar(100) NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_emergencycare" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(20) NOT NULL, "other_category" varchar(100) NULL, "number_of_animals_affected" integer NOT NULL, "name_of_affected_animal" varchar(100) NOT NULL, "registration_number" varchar(50) NULL, "registration_date" date NOT NULL, "emergency_category" varchar(50) NOT NULL, "condition_of_emergency" varchar(20) NOT NULL, "case_history" varchar(100) NULL, "clinical_signs" varchar(100) NULL, "prognosis" varchar(100) NOT NULL, "differential_diagnosis" varchar(200) NOT NULL, "final_diagnosis" varchar(100) NULL, "referral_status" bool NOT NULL, "treatment_plan" varchar(100) NULL, "drugs_of_choice" varchar(100) NULL, "owner_name" varchar(100) NOT NULL, "village" varchar(100) NOT NULL, "contact" varchar(15) NOT NULL, "service_provided_by" varchar(100) NOT NULL, "vet_registration_number" varchar(50) NULL, "vet_contact" varchar(15) NULL, "signature_and_stamp" text NULL, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_farmconsultation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "area_of_interest" varchar(20) NOT NULL, "other" varchar(255) NULL, "recommendation" text NULL, "manager" varchar(30) NOT NULL, "farmer_name" varchar(255) NOT NULL, "contact" varchar(15) NOT NULL, "village" varchar(255) NOT NULL, "vet_name" varchar(255) NOT NULL, "vet_reg_no" varchar(255) NOT NULL, "vet_contact" varchar(15) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "provided_by" varchar(254) NOT NULL, "visit_date" date NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_postmortemrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(10) NOT NULL, "other_livestock" varchar(100) NULL, "name_of_animal" varchar(100) NOT NULL, "sex" varchar(6) NOT NULL, "age" varchar(100) NOT NULL, "case_history" text NOT NULL, "number_of_sick_animals" integer NOT NULL, "number_of_dead" integer NOT NULL, "morbidity_rate" varchar(100) NOT NULL, "date_of_incidence" date NOT NULL, "time_of_incidence" time NOT NULL, "signs_of_cadaver" text NOT NULL, "cadaver_open_for_pm" varchar(3) NOT NULL, "reasons_for_not_opening" text NULL, "major_pathological_conditions" text NULL, "sample_sent_to_lab" varchar(3) NOT NULL, "cause_of_death_notifiable" varchar(3) NOT NULL, "cause_of_death_zoonotic" varchar(3) NOT NULL, "precautions_if_zoonotic" text NULL, "cadaver_disposed_by" varchar(7) NOT NULL, "owner_name" varchar(100) NOT NULL, "owner_village" varchar(100) NOT NULL, "owner_mobile_number" varchar(15) NOT NULL, "vet_in_charge_name" varchar(100) NOT NULL, "vet_in_charge_registration_number" varchar(100) NOT NULL, "vet_in_charge_mobile_number" varchar(15) NOT NULL, "signature" text NULL, "stamp" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "provided_by" varchar(255) NOT NULL, "vet_category" varchar(30) NOT NULL, reg_no  TEXT, cause_of_death  TEXT);
CREATE TABLE IF NOT EXISTS "portals_pregnancydiagnosis" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cow_name" varchar(255) NOT NULL, "reg_no" varchar(255) NOT NULL, "category" varchar(10) NOT NULL, "date_of_ai" date NOT NULL, "pg_diag_date" date NOT NULL, "pd_results" varchar(15) NOT NULL, "pd_method" varchar(255) NOT NULL, "positive_pd_months" decimal NOT NULL, "negative_pd_comment" text NULL, "pd_nxt_date" date NULL, "expctd_delivery_date" date NULL, "comment" text NULL, "owners_name" varchar(255) NOT NULL, "village" varchar(255) NOT NULL, "contact" varchar(15) NOT NULL, "vet_name" varchar(255) NOT NULL, "vet_reg_no" varchar(255) NOT NULL, "vet_contact" varchar(15) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "provided_by" varchar(255) NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_referral" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "species" varchar(255) NOT NULL, "treatment_duration" varchar(255) NOT NULL, "previous_treatment_state" text NOT NULL, "prognosis" varchar(30) NOT NULL, "referral_date" date NOT NULL, "referral_choice" varchar(25) NOT NULL, "r_vet_name" varchar(255) NOT NULL, "r_vet_contact" varchar(15) NOT NULL, "farmer_name" varchar(255) NOT NULL, "village" varchar(255) NOT NULL, "contact" varchar(15) NOT NULL, "vet_name" varchar(255) NOT NULL, "vet_reg_no" varchar(255) NOT NULL, "vet_contact" varchar(15) NOT NULL, "signature" text NULL, "stamp" text NULL, "comment" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "provided_by" varchar(255) NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_samplecollection" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(10) NOT NULL, "other_livestock" varchar(100) NULL, "name_of_animal" varchar(100) NOT NULL, "registration_number" varchar(100) NOT NULL, "age_of_animal" varchar(10) NOT NULL, "sex_of_animal" varchar(6) NOT NULL, "history_of_animal" text NOT NULL, "clinical_signs_of_animal" text NOT NULL, "type_of_sample_collected" varchar(20) NOT NULL, "date_of_sampling" date NOT NULL, "sample_storage_condition" varchar(100) NOT NULL, "means_of_transportation" varchar(100) NOT NULL, "sample_rating" varchar(20) NOT NULL, "owner_name" varchar(100) NOT NULL, "owner_village" varchar(100) NOT NULL, "owner_mobile_number" varchar(15) NOT NULL, "vet_in_charge_name" varchar(100) NOT NULL, "vet_in_charge_registration_number" varchar(100) NOT NULL, "vet_in_charge_mobile_number" varchar(15) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "provided_by" varchar(100) NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_uterineirrigationrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "livestock_category" varchar(20) NOT NULL, "name_of_animal" varchar(100) NOT NULL, "registration_number" varchar(100) NOT NULL, "registration_date" date NOT NULL, "number_of_repeats" integer NOT NULL, "abortion_status_history" varchar(20) NOT NULL, "rabies_status_history" varchar(20) NOT NULL, "previous_insemination_by" varchar(100) NOT NULL, "treatment_plan" text NULL, "drugs_of_choice" varchar(200) NULL, "comment" text NULL, "owner_name" varchar(100) NOT NULL, "village" varchar(100) NOT NULL, "contact" varchar(15) NOT NULL, "service_provided_by" varchar(100) NOT NULL, "vet_in_charge" varchar(100) NULL, "registration_number_vet" varchar(100) NULL, "contact_vet" varchar(15) NULL, "sign_and_stamp" text NULL, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "exp_ex_date" date NOT NULL, "reason" varchar(20) NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_vaccinationrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "species_targeted" varchar(20) NOT NULL, "other_species" varchar(255) NULL, "number_of_animals_vaccinated" integer NOT NULL, "age_of_animal" varchar(50) NOT NULL, "sex_of_animal" varchar(10) NOT NULL, "breed_of_animal" varchar(100) NOT NULL, "color_of_animal" varchar(100) NOT NULL, "other_description" text NULL, "vaccination_of" varchar(20) NOT NULL, "vaccines_used" varchar(255) NOT NULL, "batch_number" varchar(255) NOT NULL, "date_of_vaccination" date NOT NULL, "vaccination_type" varchar(10) NOT NULL, "next_date_of_vaccination" date NOT NULL, "name_of_rash" varchar(255) NULL, "village_vaccination_done" varchar(255) NULL, "nature_of_vaccination_program" varchar(10) NOT NULL, "name_of_owner" varchar(255) NOT NULL, "village" varchar(255) NOT NULL, "contact" varchar(50) NOT NULL, "name_of_vet_incharge" varchar(255) NOT NULL, "registration_number" varchar(255) NOT NULL, "mobile_number" varchar(20) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "dosage" varchar(255) NOT NULL, "expiry_date" date NOT NULL, "other_disease" varchar(255) NOT NULL, "sub_county" varchar(255) NOT NULL, "ward" varchar(255) NOT NULL, "provided_by" varchar(255) NOT NULL, "vet_category" varchar(30) NOT NULL, "assigned_by_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_veterinarybilling" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "billing_category" varchar(100) NOT NULL, "total_amount_billed" decimal NOT NULL, "total_paid" decimal NOT NULL, "balance" decimal NOT NULL, "mode_of_payment" varchar(20) NOT NULL, "agreed_date" date NOT NULL, "payment_plan" varchar(50) NOT NULL, "farmer_name" varchar(255) NOT NULL, "village" varchar(255) NOT NULL, "contact" varchar(15) NOT NULL, "vet_to_be_paid" varchar(255) NOT NULL, "reg_no" varchar(255) NOT NULL, "vet_contact" varchar(15) NOT NULL, "signature" text NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "payment_status" varchar(50) NOT NULL, "provided_by" varchar(100) NOT NULL, "other_billing_category" varchar(50) NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_dailykill" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "livestock_category" varchar(50) NOT NULL, "total_kills_per_day" integer unsigned NOT NULL CHECK ("total_kills_per_day" >= 0), "condemnation_done" varchar(30) NOT NULL, "condemnation_status" varchar(50) NULL, "comment_by_inspector" text NULL, "inspector_name" varchar(100) NOT NULL, "inspector_reg_number" varchar(50) NOT NULL, "inspector_status" varchar(50) NOT NULL, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_by_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_to_official_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_question" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "text" text NOT NULL, "correct_answer" varchar(1) NOT NULL, "option_a" varchar(255) NOT NULL, "option_b" varchar(255) NOT NULL, "option_c" varchar(255) NOT NULL, "option_d" varchar(255) NOT NULL, "moderator" varchar(255) NOT NULL, moderator_id INTEGER DEFAULT 1);
CREATE TABLE portals_moderator (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name VARCHAR(255) NOT NULL
);
CREATE TABLE IF NOT EXISTS "portals_vetjudgment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "date_of_judgment" date NOT NULL, "emergency_condition" varchar(50) NULL, "kvb_no" varchar(100) NULL, "livestock_category" varchar(20) NOT NULL, "non_emergency_condition" varchar(50) NULL, "other_livestock_category" varchar(255) NULL, "practitioner_judgment" varchar(25) NOT NULL, "prescription_details" text NULL, "prognosis" varchar(10) NOT NULL, "referral_details" text NULL, "request_type" varchar(15) NOT NULL, "telemedicine_category" varchar(20) NOT NULL, "tentative_diagnosis" text NOT NULL, "vet_category" varchar(100) NULL, "vet_contact" varchar(13) NULL, "vet_name" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_clinicalrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "animal_species_affected" varchar(20) NOT NULL, "other_species" varchar(100) NULL, "name_of_animal_affected" varchar(100) NOT NULL, "registration_number" varchar(100) NOT NULL, "age_of_animal" varchar(20) NOT NULL, "breed_of_animal" varchar(100) NOT NULL, "nature_of_disease" varchar(20) NOT NULL, "clinical_signs" text NOT NULL, "differential_diagnosis" text NOT NULL, "final_diagnosis" text NOT NULL, "case_history" text NOT NULL, "treatment_plan" text NOT NULL, "drugs_of_choice" text NOT NULL, "prognosis" varchar(20) NOT NULL, "date_of_start_dose" date NOT NULL, "final_treatment_date" date NULL, "is_zoonotic" varchar(3) NOT NULL, "precautions" text NULL, "refer_case_to_other_vet" varchar(3) NOT NULL, "is_disease_notifiable" varchar(3) NOT NULL, "notified_authority" varchar(3) NOT NULL, "comment" text NULL, "owner_name" varchar(100) NOT NULL, "owner_village" varchar(100) NOT NULL, "owner_contact" varchar(15) NOT NULL, "vet_in_charge_name" varchar(100) NOT NULL, "vet_registration_number" varchar(100) NOT NULL, "vet_contact" varchar(15) NOT NULL, "vet_signature" text NULL, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "provided_by" varchar(255) NOT NULL, "vet_category" varchar(30) NOT NULL);
CREATE TABLE IF NOT EXISTS "portals_invoice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "invoice_category" varchar(50) NOT NULL, "date_of_invoice" date NOT NULL, "total_amount_due" decimal NOT NULL, "farmer_name" varchar(100) NOT NULL, "village" varchar(100) NOT NULL, "contact" varchar(15) NOT NULL, "vet_in_charge_of_invoice" varchar(100) NOT NULL, "vet_registration_number" varchar(100) NOT NULL, "vet_contact" varchar(15) NOT NULL, "signature" varchar(100) NULL, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "invoice_particulars" varchar(200) NOT NULL, "other_invoice_category" varchar(100) NOT NULL, "provided_by" varchar(40) NOT NULL, "vet_category" varchar(30) NOT NULL, "payment_method" varchar(30) NOT NULL);
CREATE TABLE portals_payment (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    merchant_request_id TEXT NOT NULL,
    checkout_request_id TEXT NOT NULL,
    amount REAL NOT NULL,
    phone_number TEXT NOT NULL,
    mpesa_receipt TEXT UNIQUE,
    status TEXT DEFAULT 'Pending',
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
, "lesson_id" bigint NULL REFERENCES "portals_tutorial" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "portals_clientrequest" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "assigned_to_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "consent" bool NOT NULL, "consultation_fee" decimal NOT NULL, "contact" varchar(13) NOT NULL, "date_of_request" date NULL, "emergency_condition" varchar(50) NULL, "farmer_name" varchar(100) NOT NULL, "livestock_category" varchar(20) NOT NULL, "location" varchar(100) NOT NULL, "other_livestock_category" varchar(255) NULL, "photo" varchar(100) NULL, "request_type" varchar(15) NOT NULL, "time_of_request" time NULL, "non_emergency_condition" varchar(50) NULL, "case_history" text NULL, "communication_methods" varchar(15) NOT NULL, "assigned_by_id" bigint NULL REFERENCES "user_user" ("id") DEFERRABLE INITIALLY DEFERRED, "judgement" bool NOT NULL, "telemedicine_category" varchar(20) NOT NULL, "status" varchar(10) NULL, assigned_by INTEGER REFERENCES auth_user(id) NULL);
